const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Workspace ─────────────────────────────────────────────────────────────────\n\nmodel Workspace {\n  id              String   @id @default(cuid())\n  name            String\n  slug            String   @unique\n  baseCurrency    String   @default(\"KWD\")\n  taxRate         Decimal  @default(15) @db.Decimal(5, 2)\n  logo            String?\n  // Branding slot (BrandingSlotId) whose asset is shown on invoices.\n  invoiceLogoSlot String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  members            WorkspaceMember[]\n  activityLogs       ActivityLog[]\n  industries         Industry[]\n  referrals          Referral[]\n  companies          Company[]\n  contacts           Contact[]\n  services           Service[]\n  deals              Deal[]\n  projects           Project[]\n  invoices           Invoice[]\n  payments           Payment[]\n  pipelines          Pipeline[]\n  projectStatuses    ProjectStatus[]\n  taskStatuses       TaskStatus[]\n  customFields       CustomFieldDef[]\n  whatsappConfig     WhatsAppConfig?\n  whatsappTemplates  WhatsAppTemplate[]\n  integrations       IntegrationCredential[]\n  roles              Role[]\n  titles             Title[]\n  currencies         Currency[]\n  exchangeRates      ExchangeRate[]\n  attachments        Attachment[]\n  checklistTemplates ChecklistTemplate[]\n  conversations      Conversation[]\n  publishItems       PublishItem[]\n}\n\n// ─── Currencies & Exchange Rates ──────────────────────────────────────────────\n\nmodel Currency {\n  id          String   @id @default(cuid())\n  workspaceId String\n  code        String // ISO: \"KWD\", \"SAR\", \"USD\", \"EUR\"\n  name        String // \"Kuwaiti Dinar\", \"Saudi Riyal\"\n  symbol      String // \"د.ك\", \"﷼\", \"$\"\n  isBase      Boolean  @default(false)\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, code])\n}\n\nmodel ExchangeRate {\n  id            String   @id @default(cuid())\n  workspaceId   String\n  fromCurrency  String // e.g. \"SAR\"\n  toCurrency    String // always base currency e.g. \"KWD\"\n  rate          Decimal  @db.Decimal(12, 6) // 1 fromCurrency = X toCurrency\n  effectiveDate DateTime @default(now())\n  createdAt     DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, fromCurrency, toCurrency])\n}\n\n// ─── Team & Roles ──────────────────────────────────────────────────────────────\n\nmodel WorkspaceMember {\n  id          String     @id @default(cuid())\n  workspaceId String\n  userId      String // Clerk user ID\n  email       String\n  name        String?\n  imageUrl    String? // Clerk/Google profile photo\n  type        MemberType @default(MEMBER)\n  roleId      String?\n  titleId     String? // capacity title (Junior A, Senior…) — effort rates, not permissions\n  weeklyHours Float      @default(40) // working-hours capacity per week\n  joinedAt    DateTime   @default(now())\n\n  workspace                Workspace                 @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  role                     Role?                     @relation(fields: [roleId], references: [id])\n  capacityTitle            Title?                    @relation(fields: [titleId], references: [id], onDelete: SetNull)\n  assignedTasks            Task[]                    @relation(\"TaskAssignee\")\n  messages                 Message[]                 @relation(\"CommentAuthor\")\n  mentionedIn              MessageMention[]          @relation(\"MentionedIn\")\n  reactions                MessageReaction[]         @relation(\"ReactionAuthor\")\n  notifications            Notification[]            @relation(\"NotificationRecipient\")\n  pushSubscriptions        PushSubscription[]\n  scheduledItems           PublishItem[]             @relation(\"PublishScheduler\")\n  projectMemberships       ProjectMember[]           @relation(\"ProjectTeam\")\n  statusChanges            TaskStatusChange[]        @relation(\"StatusChangeMember\")\n  conversations            ConversationParticipant[] @relation(\"ConversationMember\")\n  responsibleWeeklyTargets ProjectWeeklyTarget[]     @relation(\"WeeklyTargetResponsible\")\n  assignedWeeklySlots      WeeklySlot[]              @relation(\"WeeklySlotAssignee\")\n\n  @@unique([workspaceId, userId])\n  @@index([userId])\n}\n\nenum MemberType {\n  OWNER\n  MEMBER\n  FREELANCER\n}\n\nmodel Role {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  permissions Json // { deals: \"full\", invoices: \"view\", ... }\n  createdAt   DateTime @default(now())\n\n  workspace      Workspace         @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  members        WorkspaceMember[]\n  projectMembers ProjectMember[]\n\n  @@unique([workspaceId, name])\n}\n\n// ─── Capacity Titles ───────────────────────────────────────────────────────────\n// A Title (Junior A, Junior B, Senior, Creator…) carries effort rates: how many\n// minutes of work a unit of content costs for people holding that title.\n// Separate from Role, which is permissions only.\n\nmodel Title {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  createdAt   DateTime @default(now())\n\n  workspace  Workspace         @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  members    WorkspaceMember[]\n  fieldRates TitleFieldRate[]\n  stageRates TitleStageRate[]\n\n  @@unique([workspaceId, name])\n}\n\n// Rate for one checklist-template field: minutes per unit of that field's\n// effortUnit (per word, per audio minute, per video minute). For \"fixed\"\n// fields the quantity is always 1, so this doubles as flat minutes.\nmodel TitleFieldRate {\n  id             String @id @default(cuid())\n  titleId        String\n  templateItemId String\n  minutesPerUnit Float\n\n  title        Title                 @relation(fields: [titleId], references: [id], onDelete: Cascade)\n  templateItem ChecklistTemplateItem @relation(fields: [templateItemId], references: [id], onDelete: Cascade)\n\n  @@unique([titleId, templateItemId])\n}\n\n// Flat minutes charged each time a task passes through a stage (review stages).\nmodel TitleStageRate {\n  id             String @id @default(cuid())\n  titleId        String\n  statusId       String\n  minutesPerPass Float\n\n  title  Title      @relation(fields: [titleId], references: [id], onDelete: Cascade)\n  status TaskStatus @relation(\"TitleStageRates\", fields: [statusId], references: [id], onDelete: Cascade)\n\n  @@unique([titleId, statusId])\n}\n\n// ─── Freelancer Access ─────────────────────────────────────────────────────────\n\nmodel ProjectCollaborator {\n  id         String             @id @default(cuid())\n  projectId  String\n  memberId   String\n  status     CollaboratorStatus @default(PENDING)\n  invitedAt  DateTime           @default(now())\n  invitedVia String? // \"whatsapp\" | \"email\"\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n}\n\nenum CollaboratorStatus {\n  PENDING\n  ACTIVE\n  REVOKED\n}\n\n// ─── Companies & Contacts ──────────────────────────────────────────────────────\n\nmodel Company {\n  id             String    @id @default(cuid())\n  workspaceId    String\n  ownerId        String? // Clerk user ID of record owner\n  ownerName      String?\n  name           String\n  nameAr         String?\n  industry       String?\n  referral       String?\n  phone          String?\n  whatsappNumber String?\n  email          String?\n  website        String?\n  address        String?\n  countries      String[]  @default([]) // ISO2 codes of operating countries\n  logo           String?\n  notes          String?\n  customFields   Json?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  deletedAt      DateTime?\n  deletedBy      String? // WorkspaceMember ID of who trashed it\n\n  workspace Workspace        @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  contacts  ContactCompany[]\n  deals     Deal[]\n  projects  Project[]\n\n  @@index([workspaceId, deletedAt])\n}\n\nmodel Contact {\n  id           String    @id @default(cuid())\n  workspaceId  String\n  ownerId      String? // Clerk user ID of record owner\n  ownerName    String?\n  firstName    String\n  middleName   String?\n  lastName     String\n  nameAr       String?\n  mobile       String\n  email        String?\n  role         String?\n  country      String\n  notes        String?\n  customFields Json?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  deletedAt    DateTime?\n  deletedBy    String? // WorkspaceMember ID of who trashed it\n\n  workspace        Workspace         @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  companies        ContactCompany[]\n  deals            Deal[]\n  invoices         Invoice[]\n  whatsappMessages WhatsAppMessage[]\n\n  @@unique([workspaceId, mobile])\n  @@index([workspaceId, deletedAt])\n}\n\nmodel ContactCompany {\n  id        String   @id @default(cuid())\n  contactId String\n  companyId String\n  role      String? // Role at this specific company\n  primary   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  contact Contact @relation(fields: [contactId], references: [id], onDelete: Cascade)\n  company Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  @@unique([contactId, companyId])\n}\n\n// ─── Services Catalog ──────────────────────────────────────────────────────────\n\nmodel Service {\n  id          String      @id @default(cuid())\n  workspaceId String\n  name        String\n  description String?\n  pricingType PricingType @default(FIXED)\n  unitPrice   Decimal     @db.Decimal(12, 2)\n  unit        String? // \"month\", \"piece\", \"hour\", etc.\n  taxable     Boolean     @default(true)\n  active      Boolean     @default(true)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  workspace Workspace  @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  dealItems DealItem[]\n  tasks     Task[]\n}\n\nenum PricingType {\n  FIXED\n  MONTHLY\n  PER_UNIT\n  HOURLY\n}\n\n// ─── Pipelines & Stages (Dynamic) ─────────────────────────────────────────────\n\nmodel Pipeline {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  isDefault   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace       @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  stages    PipelineStage[]\n  deals     Deal[]\n\n  @@index([workspaceId, isDefault])\n}\n\nmodel PipelineStage {\n  id         String    @id @default(cuid())\n  pipelineId String\n  name       String\n  order      Int\n  color      String    @default(\"#3b82f6\")\n  type       StageType @default(OPEN)\n  createdAt  DateTime  @default(now())\n\n  pipeline Pipeline @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  deals    Deal[]\n\n  @@unique([pipelineId, order])\n}\n\nenum StageType {\n  OPEN\n  WON\n  LOST\n}\n\n// ─── Deals ─────────────────────────────────────────────────────────────────────\n\nmodel Deal {\n  id                String    @id @default(cuid())\n  workspaceId       String\n  pipelineId        String\n  stageId           String\n  companyId         String?\n  contactId         String?\n  ownerId           String? // Clerk user ID of record owner\n  ownerName         String?\n  title             String\n  value             Decimal   @db.Decimal(12, 2)\n  currency          String    @default(\"KWD\")\n  rateToBase        Decimal?  @db.Decimal(12, 6) // Locked exchange rate at time of creation\n  valueInBase       Decimal?  @db.Decimal(12, 2) // Value converted to base currency using locked rate\n  expectedCloseDate DateTime?\n  discountType      String    @default(\"percent\") // \"percent\" or \"fixed\"\n  discountValue     Decimal   @default(0) @db.Decimal(12, 3)\n  lostReason        String?\n  notes             String?\n  customFields      Json?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n  closedAt          DateTime?\n  deletedAt         DateTime?\n  deletedBy         String? // WorkspaceMember ID of who trashed it\n\n  workspace    Workspace     @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  pipeline     Pipeline      @relation(fields: [pipelineId], references: [id])\n  stage        PipelineStage @relation(fields: [stageId], references: [id])\n  company      Company?      @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  contact      Contact?      @relation(fields: [contactId], references: [id], onDelete: SetNull)\n  items        DealItem[]\n  project      Project?\n  accessGrants DealAccess[]\n  invoices     Invoice[]\n\n  @@index([workspaceId, deletedAt])\n}\n\nmodel DealAccess {\n  id          String    @id @default(cuid())\n  dealId      String\n  email       String\n  name        String?\n  token       String    @unique @default(cuid())\n  permissions Json // { project: true, invoices: true, tasks: true }\n  createdAt   DateTime  @default(now())\n  expiresAt   DateTime?\n\n  deal Deal @relation(fields: [dealId], references: [id], onDelete: Cascade)\n\n  @@unique([dealId, email])\n}\n\nmodel DealItem {\n  id          String  @id @default(cuid())\n  dealId      String\n  serviceId   String\n  quantity    Int     @default(1)\n  unitPrice   Decimal @db.Decimal(12, 2)\n  description String? // Override description for this deal\n\n  deal    Deal    @relation(fields: [dealId], references: [id], onDelete: Cascade)\n  service Service @relation(fields: [serviceId], references: [id])\n\n  @@index([dealId])\n}\n\n// ─── Projects ──────────────────────────────────────────────────────────────────\n\nmodel ProjectStatus {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  order       Int\n  color       String   @default(\"#3b82f6\")\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  projects  Project[]\n\n  @@unique([workspaceId, order])\n}\n\nmodel Project {\n  id                String    @id @default(cuid())\n  workspaceId       String\n  dealId            String?   @unique\n  companyId         String?\n  contactId         String?\n  ownerId           String? // Clerk user ID of record owner\n  ownerName         String?\n  statusId          String?\n  name              String\n  type              String    @default(\"fixed\") // \"fixed\" or \"recurring\"\n  thumbnailId       String? // File ID for project thumbnail\n  description       String?\n  requirePublishing Boolean   @default(false)\n  startDate         DateTime?\n  deadline          DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n  deletedAt         DateTime?\n  deletedBy         String? // WorkspaceMember ID of who trashed it\n\n  workspace        Workspace             @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  deal             Deal?                 @relation(fields: [dealId], references: [id], onDelete: SetNull)\n  company          Company?              @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  status           ProjectStatus?        @relation(fields: [statusId], references: [id])\n  tasks            Task[]\n  invoices         Invoice[]\n  collaborators    ProjectCollaborator[]\n  projectTemplates ProjectTemplate[]\n  folders          ProjectFolder[]\n  assets           ProjectAsset[]\n  publishItems     PublishItem[]\n  members          ProjectMember[]\n  messages         Message[]\n  weeklyTargets    ProjectWeeklyTarget[]\n  weeklySlots      WeeklySlot[]\n\n  @@index([workspaceId, deletedAt])\n}\n\n// ─── Weekly Plan ────────────────────────────────────────────────────────────────\n\n// Per-project weekly capacity: how many tasks of each type the project should\n// deliver per week. Drives the empty slots shown in the Todo column.\nmodel ProjectWeeklyTarget {\n  id                  String   @id @default(cuid())\n  projectId           String\n  templateId          String\n  // Tasks to deliver per week on the unified calendar (Sunday-start weeks,\n  // due Thursday end-of-day).\n  perWeek             Int      @default(0)\n  // Cadence: slots are produced every N weeks (1 = weekly, 2 = biweekly…),\n  // counted from startsOn's week. Off-weeks produce no slots.\n  intervalWeeks       Int      @default(1)\n  // First planned week (Sunday 00:00 Kuwait). A plan saved with \"starts next\n  // week\" shows its first slots under \"Next week\" instead of \"Due\".\n  startsOn            DateTime @default(now())\n  // Project member responsible for filling this template's weekly slots.\n  responsibleMemberId String?\n\n  project           Project           @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  template          ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  responsibleMember WorkspaceMember?  @relation(\"WeeklyTargetResponsible\", fields: [responsibleMemberId], references: [id], onDelete: SetNull)\n\n  @@unique([projectId, templateId])\n}\n\n// One row per Todo slot per week. Seeded lazily from the weekly targets when\n// the board loads; a slot is \"filled\" once a task claims it by moving into\n// Todo. Admins can soft-remove empty slots for the current week (removedAt).\nmodel WeeklySlot {\n  id         String    @id @default(cuid())\n  projectId  String\n  templateId String\n  weekStart  DateTime // Sunday 00:00 Kuwait — the unified week grid (stored as UTC)\n  taskId     String?   @unique\n  assigneeId String? // Member responsible for filling this slot\n  dueDate    DateTime? // Explicit deadline (force-added slots); falls back to Thursday 23:59 of the week\n  removedAt  DateTime?\n  createdAt  DateTime  @default(now())\n\n  project  Project           @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  template ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  task     Task?             @relation(fields: [taskId], references: [id], onDelete: SetNull)\n  assignee WorkspaceMember?  @relation(\"WeeklySlotAssignee\", fields: [assigneeId], references: [id], onDelete: SetNull)\n\n  @@index([projectId, weekStart])\n  @@index([assigneeId, weekStart])\n  // Todo gate: free-slot lookup / count by type within the week.\n  @@index([projectId, templateId, weekStart])\n}\n\nmodel ProjectMember {\n  id        String   @id @default(cuid())\n  projectId String\n  memberId  String\n  roleId    String?\n  addedAt   DateTime @default(now())\n\n  project Project         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  member  WorkspaceMember @relation(\"ProjectTeam\", fields: [memberId], references: [id], onDelete: Cascade)\n  role    Role?           @relation(fields: [roleId], references: [id], onDelete: SetNull)\n\n  @@unique([projectId, memberId])\n  @@index([memberId])\n}\n\n// ─── Project Assets ─────────────────────────────────────────────────────────────\n\nmodel ProjectFolder {\n  id        String    @id @default(cuid())\n  projectId String\n  parentId  String?\n  name      String\n  createdAt DateTime  @default(now())\n  deletedAt DateTime?\n  deletedBy String? // WorkspaceMember ID of who trashed it\n\n  project  Project         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  parent   ProjectFolder?  @relation(\"FolderTree\", fields: [parentId], references: [id], onDelete: Cascade)\n  children ProjectFolder[] @relation(\"FolderTree\")\n  assets   ProjectAsset[]\n\n  @@index([projectId, parentId])\n}\n\nmodel ProjectAsset {\n  id          String    @id @default(cuid())\n  projectId   String\n  folderId    String?\n  name        String\n  fileSize    Int\n  contentType String\n  r2Key       String\n  uploadedBy  String?\n  createdAt   DateTime  @default(now())\n  deletedAt   DateTime?\n  deletedBy   String? // WorkspaceMember ID of who trashed it\n\n  project Project        @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  folder  ProjectFolder? @relation(fields: [folderId], references: [id], onDelete: Cascade)\n\n  @@index([projectId, folderId])\n}\n\n// ─── Checklist Templates ────────────────────────────────────────────────────────\n\nmodel ChecklistTemplate {\n  id                     String   @id @default(cuid())\n  workspaceId            String\n  name                   String\n  icon                   String?\n  color                  String? // hex color e.g. \"#22d3ee\"\n  description            String?\n  publishToCalendar      Boolean  @default(true) // completed tasks of this type go to the publish calendar\n  // Lock rule for the built-in task Title, same semantics as field locks:\n  // null = Auto (locks once the task leaves Todo), stage id = locks from that\n  // stage, titleNeverLock = editable at every stage.\n  titleLockedFromStageId String?\n  titleNeverLock         Boolean  @default(false)\n  // Custom display of the built-in Title on task forms — rendering only,\n  // tasks still store a plain Task.title. Null = default \"Task Title\" copy.\n  titleLabel             String?\n  titleHelp              String?\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n\n  workspace            Workspace               @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  titleLockedFromStage TaskStatus?             @relation(\"TitleLockedFromStage\", fields: [titleLockedFromStageId], references: [id], onDelete: SetNull)\n  items                ChecklistTemplateItem[]\n  sections             ChecklistSection[]\n  projects             ProjectTemplate[]\n  weeklyTargets        ProjectWeeklyTarget[]\n  tasks                Task[]                  @relation(\"TaskType\")\n  weeklySlots          WeeklySlot[]\n}\n\n// A named group of checklist fields on a task type (e.g. \"Requirements\",\n// \"Delivery\", \"Raw Assets\"). Sections are renamable, addable, and removable;\n// their `phase` carries the behavior the rest of the app keys on:\n// \"create\" = filled on the new-task form, locks after Todo (Requirements-like);\n// \"delivery\" = filled during work, gated behind leaving Todo (Delivery-like).\n// Items mirror their section's phase so all stage-gate logic stays unchanged.\nmodel ChecklistSection {\n  id         String   @id @default(cuid())\n  templateId String\n  name       String\n  phase      String   @default(\"delivery\") // \"create\" or \"delivery\"\n  order      Int      @default(0)\n  createdAt  DateTime @default(now())\n\n  template ChecklistTemplate       @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  items    ChecklistTemplateItem[]\n\n  @@index([templateId])\n}\n\nmodel ChecklistTemplateItem {\n  id                    String  @id @default(cuid())\n  templateId            String\n  name                  String\n  type                  String  @default(\"text\") // \"text\", \"select\", \"file_upload\", \"textarea\", \"link\", \"yes_no\", \"checkbox\"\n  role                  String  @default(\"any\")\n  options               String? // JSON array for select type e.g. '[\"Option A\",\"Option B\"]'\n  allowedFileTypes      String?\n  allowedFormats        String? // JSON array e.g. '[\"mp4\",\"mov\"]'\n  aspectRatio           String? // e.g. \"16:9\", \"9:16\", \"1:1\"\n  mandatory             Boolean @default(false)\n  phase                 String  @default(\"create\") // \"create\" or \"delivery\" — mirrors the section's phase\n  sectionId             String? // owning section; null = legacy, grouped by phase\n  visibleFromStageId    String?\n  requiredBeforeStageId String?\n  lockedFromStageId     String?\n  neverLock             Boolean @default(false) // field stays editable at every stage\n  publishCard           String  @default(\"hidden\") // placement on the publish card: \"hidden\" | \"expanded\" | \"always\"\n  hidden                Boolean @default(false) // disabled: kept (with task data) but not shown or enforced anywhere\n  // Effort measurement: null = no effort, or \"words\" | \"audio_min\" | \"video_min\" | \"fixed\"\n  effortUnit            String?\n  order                 Int     @default(0)\n\n  template            ChecklistTemplate   @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  section             ChecklistSection?   @relation(fields: [sectionId], references: [id], onDelete: SetNull)\n  visibleFromStage    TaskStatus?         @relation(\"VisibleFromStage\", fields: [visibleFromStageId], references: [id], onDelete: SetNull)\n  requiredBeforeStage TaskStatus?         @relation(\"RequiredBeforeStage\", fields: [requiredBeforeStageId], references: [id], onDelete: SetNull)\n  lockedFromStage     TaskStatus?         @relation(\"LockedFromStage\", fields: [lockedFromStageId], references: [id], onDelete: SetNull)\n  taskItems           TaskChecklistItem[]\n  titleRates          TitleFieldRate[]\n\n  @@index([templateId])\n}\n\nmodel ProjectTemplate {\n  id         String @id @default(cuid())\n  projectId  String\n  templateId String\n\n  project  Project           @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  template ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, templateId])\n}\n\nmodel TaskChecklistItem {\n  id                    String    @id @default(cuid())\n  taskId                String\n  templateItemId        String?\n  name                  String\n  type                  String    @default(\"text\")\n  role                  String    @default(\"any\")\n  options               String?\n  allowedFileTypes      String?\n  allowedFormats        String? // JSON array e.g. '[\"mp4\",\"mov\"]'\n  aspectRatio           String? // e.g. \"16:9\", \"9:16\", \"1:1\"\n  mandatory             Boolean   @default(false)\n  phase                 String    @default(\"create\") // \"create\" or \"delivery\"\n  visibleFromStageId    String?\n  requiredBeforeStageId String?\n  lockedFromStageId     String?\n  neverLock             Boolean   @default(false) // field stays editable at every stage\n  publishCard           String    @default(\"hidden\") // placement on the publish card: \"hidden\" | \"expanded\" | \"always\"\n  hidden                Boolean   @default(false) // disabled: kept (with task data) but not shown or enforced anywhere\n  effortUnit            String? // snapshot: null | \"words\" | \"audio_min\" | \"video_min\" | \"fixed\"\n  completed             Boolean   @default(false)\n  attachmentId          String?\n  textValue             String?\n  completedAt           DateTime?\n  completedBy           String?\n  // Effort locked at field completion — only changes on explicit Recalculate.\n  effortQuantity        Float?\n  effortRate            Float?\n  effortMinutes         Float?\n  effortLockedAt        DateTime?\n  order                 Int       @default(0)\n\n  task         Task                   @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  templateItem ChecklistTemplateItem? @relation(fields: [templateItemId], references: [id], onDelete: SetNull)\n\n  // One row per template field per task — concurrent getTask materialisation\n  // can't duplicate fields (NULL templateItemId = custom rows, exempt).\n  @@unique([taskId, templateItemId])\n  @@index([taskId])\n  @@index([templateItemId])\n  // Title-wide effort recalculation filters on these.\n  @@index([completedBy, effortLockedAt])\n}\n\n// ─── Tasks ─────────────────────────────────────────────────────────────────────\n\nmodel TaskStatus {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  order       Int\n  color       String   @default(\"#3b82f6\")\n  createdAt   DateTime @default(now())\n\n  workspace           Workspace               @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  tasks               Task[]\n  visibleFromItems    ChecklistTemplateItem[] @relation(\"VisibleFromStage\")\n  requiredBeforeItems ChecklistTemplateItem[] @relation(\"RequiredBeforeStage\")\n  lockedFromItems     ChecklistTemplateItem[] @relation(\"LockedFromStage\")\n  titleLockTemplates  ChecklistTemplate[]     @relation(\"TitleLockedFromStage\")\n  titleStageRates     TitleStageRate[]        @relation(\"TitleStageRates\")\n\n  @@unique([workspaceId, order])\n}\n\nmodel Task {\n  id                String    @id @default(cuid())\n  projectId         String\n  taskNumber        Int       @default(0)\n  serviceId         String?\n  statusId          String?\n  assigneeId        String?\n  // Task type (ChecklistTemplate). Stored directly so the type survives even\n  // when the template has no fields (nothing to infer from checklist items).\n  templateId        String?\n  title             String\n  description       String?\n  billable          Boolean   @default(true)\n  price             Decimal?  @db.Decimal(12, 2)\n  publish           Boolean   @default(true) // goes to the publish calendar when completed (stamped from task type)\n  priority          Int?\n  estimateMin       Int?\n  plannedMinutes    Float? // planned video length in minutes (null = 2-min baseline)\n  dueDate           DateTime?\n  completedAt       DateTime?\n  assignmentHistory Json?\n  stageTimings      Json?\n  stageEnteredAt    DateTime?\n  rejectionCount    Int       @default(0)\n  order             Int       @default(0)\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n  deletedAt         DateTime?\n  deletedBy         String? // WorkspaceMember ID of who trashed it\n\n  project        Project             @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  service        Service?            @relation(fields: [serviceId], references: [id], onDelete: SetNull)\n  status         TaskStatus?         @relation(fields: [statusId], references: [id])\n  template       ChecklistTemplate?  @relation(\"TaskType\", fields: [templateId], references: [id], onDelete: SetNull)\n  assignee       WorkspaceMember?    @relation(\"TaskAssignee\", fields: [assigneeId], references: [id], onDelete: SetNull)\n  checklistItems TaskChecklistItem[]\n  comments       Message[]\n  publishItem    PublishItem?\n  weeklySlot     WeeklySlot?\n\n  statusChanges TaskStatusChange[]\n\n  @@index([projectId, statusId])\n  @@index([projectId, order])\n  @@index([projectId, deletedAt])\n  // Board query: live tasks per project grouped by column.\n  @@index([projectId, deletedAt, statusId])\n  @@index([projectId, templateId])\n  // Publish queue: completed/review tasks with publishing enabled.\n  @@index([statusId, publish, deletedAt])\n}\n\nmodel TaskStatusChange {\n  id             String   @id @default(cuid())\n  taskId         String\n  memberId       String?\n  action         String // \"created\", \"status_change\"\n  fromStatusId   String?\n  fromStatusName String?\n  toStatusId     String?\n  toStatusName   String?\n  durationMs     Int? // time spent in fromStatus before this move\n  createdAt      DateTime @default(now())\n\n  task   Task             @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  member WorkspaceMember? @relation(\"StatusChangeMember\", fields: [memberId], references: [id], onDelete: SetNull)\n\n  @@index([taskId, createdAt])\n}\n\n// ─── Messages (unified: task comments, rejections, project chat, DMs) ──────────\n// One model backs every message surface. A message belongs to exactly one thread:\n//   - taskId set          → task thread (comments + rejections)\n//   - projectId always set for task/project messages → project \"Everything\" feed\n//   - conversationId set   → direct/group message\n// Centrifugo delivers these live; this table is the durable source of truth.\n// NOTE: kept mapped to the original \"TaskComment\" table so existing rows survive.\n\nmodel Message {\n  id             String   @id @default(cuid())\n  taskId         String?\n  projectId      String?\n  conversationId String?\n  replyToId      String?\n  authorId       String // WorkspaceMember ID\n  body           String // Plain text with @[Name](memberId) mentions\n  kind           String   @default(\"message\") // \"message\" | \"rejection\" | \"system\"\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  task         Task?             @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  project      Project?          @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  conversation Conversation?     @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  author       WorkspaceMember   @relation(\"CommentAuthor\", fields: [authorId], references: [id], onDelete: Cascade)\n  mentions     MessageMention[]\n  reactions    MessageReaction[]\n\n  @@index([taskId, createdAt])\n  @@index([projectId, createdAt])\n  @@index([conversationId, createdAt])\n  @@map(\"TaskComment\")\n}\n\nmodel MessageReaction {\n  id        String   @id @default(cuid())\n  messageId String\n  memberId  String\n  emoji     String\n  createdAt DateTime @default(now())\n\n  message Message         @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  member  WorkspaceMember @relation(\"ReactionAuthor\", fields: [memberId], references: [id], onDelete: Cascade)\n\n  @@unique([messageId, memberId, emoji])\n  @@index([messageId])\n}\n\nmodel MessageMention {\n  id        String @id @default(cuid())\n  messageId String @map(\"commentId\")\n  memberId  String\n\n  message Message         @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  member  WorkspaceMember @relation(\"MentionedIn\", fields: [memberId], references: [id], onDelete: Cascade)\n\n  @@unique([messageId, memberId])\n  @@map(\"CommentMention\")\n}\n\n// ─── Conversations (direct + group messages) ──────────────────────────────────\n\nmodel Conversation {\n  id          String   @id @default(cuid())\n  workspaceId String\n  isGroup     Boolean  @default(false)\n  title       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  workspace    Workspace                 @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  participants ConversationParticipant[]\n  messages     Message[]\n\n  @@index([workspaceId])\n}\n\nmodel ConversationParticipant {\n  id             String    @id @default(cuid())\n  conversationId String\n  memberId       String\n  lastReadAt     DateTime?\n  createdAt      DateTime  @default(now())\n\n  conversation Conversation    @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  member       WorkspaceMember @relation(\"ConversationMember\", fields: [memberId], references: [id], onDelete: Cascade)\n\n  @@unique([conversationId, memberId])\n  @@index([memberId])\n}\n\n// ─── Notifications ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id          String   @id @default(cuid())\n  recipientId String\n  type        String // \"mention\", \"comment\", \"assignment\", \"status_change\", \"rejection\"\n  title       String\n  body        String?\n  linkUrl     String?\n  // Web-push tag the OS notification was shown with — lets us close it on\n  // other devices when this notification is read.\n  tag         String?\n  read        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  recipient WorkspaceMember @relation(\"NotificationRecipient\", fields: [recipientId], references: [id], onDelete: Cascade)\n\n  @@index([recipientId, read, createdAt])\n  // Inbox unread rollup (GROUP BY linkUrl) + mark-thread-read by linkUrl.\n  @@index([recipientId, read, linkUrl])\n}\n\nmodel PushSubscription {\n  id         String   @id @default(cuid())\n  memberId   String\n  endpoint   String   @unique\n  p256dh     String\n  auth       String\n  // Device hygiene: which browser/OS this is, and when it last synced.\n  // Subscriptions unseen for 90+ days are pruned during sync.\n  userAgent  String?\n  lastSeenAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  member WorkspaceMember @relation(fields: [memberId], references: [id], onDelete: Cascade)\n\n  @@index([memberId])\n}\n\n// ─── Invoices ──────────────────────────────────────────────────────────────────\n\nmodel Invoice {\n  id            String        @id @default(cuid())\n  workspaceId   String\n  projectId     String?\n  contactId     String?\n  dealId        String?\n  number        String // Auto-generated: INV-001, INV-002, etc.\n  status        InvoiceStatus @default(DRAFT)\n  subtotal      Decimal       @db.Decimal(12, 2)\n  taxAmount     Decimal       @db.Decimal(12, 2)\n  discountType  String        @default(\"percent\") // \"percent\" or \"fixed\"\n  discountValue Decimal       @default(0) @db.Decimal(12, 3)\n  total         Decimal       @db.Decimal(12, 2)\n  rateToBase    Decimal?      @db.Decimal(12, 6) // Locked exchange rate at time of creation\n  totalInBase   Decimal?      @db.Decimal(12, 2) // Total converted to base currency using locked rate\n  currency      String        @default(\"KWD\")\n  notes         String?\n  issueDate     DateTime?\n  dueDate       DateTime?\n  sentAt        DateTime?\n  acceptedAt    DateTime?\n  rejectedAt    DateTime?\n  paidAt        DateTime?\n  rejectionNote String?\n  publicToken   String        @unique @default(cuid()) // For public invoice link\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  workspace Workspace     @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  project   Project?      @relation(fields: [projectId], references: [id], onDelete: SetNull)\n  contact   Contact?      @relation(fields: [contactId], references: [id], onDelete: SetNull)\n  deal      Deal?         @relation(fields: [dealId], references: [id], onDelete: SetNull)\n  items     InvoiceItem[]\n  payments  Payment[]\n\n  @@index([workspaceId, status])\n  @@index([workspaceId, createdAt])\n}\n\nenum InvoiceStatus {\n  DRAFT\n  SENT\n  ACCEPTED\n  REJECTED\n  PARTIAL\n  PAID\n  CANCELLED\n}\n\n// A payment received against an invoice (\"Payments Received\" module). The\n// sum of an invoice's payments drives its PARTIAL / PAID status.\nmodel Payment {\n  id              String   @id @default(cuid())\n  workspaceId     String\n  invoiceId       String\n  number          String // Sequential: \"1071\", \"1072\", ...\n  date            DateTime\n  location        String?\n  type            String   @default(\"Invoice Payment\") // Invoice Payment | Retainer | Advance\n  mode            String   @default(\"Bank Transfer\") // Cash | Check | Bank Transfer | Credit Card | Other\n  referenceNumber String?\n  amount          Decimal  @db.Decimal(12, 3)\n  currency        String\n  notes           String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  invoice   Invoice   @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, number])\n  @@index([workspaceId, date])\n  @@index([invoiceId])\n}\n\nmodel InvoiceItem {\n  id          String   @id @default(cuid())\n  invoiceId   String\n  description String\n  details     String? // Longer description shown under the item title\n  quantity    Int      @default(1)\n  unitPrice   Decimal  @db.Decimal(12, 2)\n  taxPct      Decimal? @db.Decimal(5, 2) // Per-item tax percentage\n  total       Decimal  @db.Decimal(12, 2)\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n}\n\n// ─── Integrations ─────────────────────────────────────────────────────────────\n\n// Third-party credentials, one row per workspace per provider. `secrets` is an\n// AES-256-GCM blob (see src/lib/secrets.ts) holding every field for the\n// provider; `hints` carries the masked forms that are safe to render.\nmodel IntegrationCredential {\n  id              String    @id @default(cuid())\n  workspaceId     String\n  provider        String // IntegrationProvider id, e.g. \"openai\"\n  secrets         String // encrypted JSON: { [fieldKey]: value }\n  hints           Json? // { [fieldKey]: \"sk-••••4f2a\" } for display only\n  enabled         Boolean   @default(true)\n  lastVerifiedAt  DateTime?\n  lastVerifyError String?\n  updatedBy       String? // WorkspaceMember ID\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, provider])\n}\n\n// ─── WhatsApp ──────────────────────────────────────────────────────────────────\n\nmodel WhatsAppConfig {\n  id            String   @id @default(cuid())\n  workspaceId   String   @unique\n  phoneNumberId String\n  accessToken   String\n  verifyToken   String\n  businessName  String?\n  connected     Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n}\n\nmodel WhatsAppTemplate {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  event       String // \"invoice_sent\", \"invoice_reminder\", \"deal_update\", etc.\n  body        String // Template with {{variables}}\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, event])\n}\n\nmodel WhatsAppMessage {\n  id          String           @id @default(cuid())\n  contactId   String\n  direction   MessageDirection\n  body        String\n  templateId  String?\n  status      MessageStatus    @default(PENDING)\n  linkedType  String? // \"invoice\", \"deal\", \"project\"\n  linkedId    String?\n  sentAt      DateTime?\n  deliveredAt DateTime?\n  readAt      DateTime?\n  createdAt   DateTime         @default(now())\n\n  contact Contact @relation(fields: [contactId], references: [id], onDelete: Cascade)\n}\n\nenum MessageDirection {\n  INBOUND\n  OUTBOUND\n}\n\nenum MessageStatus {\n  PENDING\n  SENT\n  DELIVERED\n  READ\n  FAILED\n}\n\n// ─── Activity Log ──────────────────────────────────────────────────────────────\n\nmodel ActivityLog {\n  id          String   @id @default(cuid())\n  workspaceId String\n  userId      String // Clerk user ID\n  userName    String?\n  userImage   String?\n  entityType  String // \"company\", \"contact\", \"deal\", \"project\", \"task\", \"invoice\", \"service\"\n  entityId    String\n  entityName  String? // Snapshot of the entity name at time of change\n  action      String // \"created\", \"updated\", \"deleted\", \"moved\", \"sent\", \"accepted\", \"rejected\", \"paid\"\n  changes     Json? // { field: { from: \"old\", to: \"new\" } }\n  metadata    Json? // Extra context (e.g. stage name for deal moves)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, entityType, entityId])\n  @@index([workspaceId, createdAt])\n}\n\n// ─── Industries (Dynamic) ──────────────────────────────────────────────────────\n\nmodel Industry {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, name])\n}\n\nmodel Referral {\n  id          String   @id @default(cuid())\n  workspaceId String\n  name        String\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, name])\n}\n\n// ─── Custom Fields (Dynamic) ───────────────────────────────────────────────────\n\nmodel CustomFieldDef {\n  id          String            @id @default(cuid())\n  workspaceId String\n  entityType  CustomFieldEntity\n  name        String\n  label       String\n  fieldType   CustomFieldType\n  options     Json? // For dropdown: [\"Option A\", \"Option B\"]\n  required    Boolean           @default(false)\n  order       Int               @default(0)\n  createdAt   DateTime          @default(now())\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, entityType, name])\n}\n\n// ─── Attachments (R2 File Storage) ──────────────────────────────────────────\n\nmodel Attachment {\n  id            String   @id @default(cuid())\n  workspaceId   String\n  entityType    String // \"company\", \"contact\", \"deal\", \"project\", \"invoice\", \"task\", \"logo\"\n  entityId      String // ID of the parent record\n  name          String\n  sizeBytes     Int?\n  contentType   String?\n  durationSec   Float? // media duration captured client-side at upload (audio/video)\n  r2Key         String?\n  status        String   @default(\"uploading\") // uploading | uploaded | failed\n  uploadId      String? // R2 multipart upload ID\n  totalParts    Int      @default(1)\n  uploadedParts Json     @default(\"[]\")\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, entityType, entityId])\n  // Effort/duration lookups query by entity without workspaceId.\n  @@index([entityType, entityId, status])\n  @@index([r2Key])\n}\n\n// ─── Login Page Gallery ─────────────────────────────────────────────────────────\n// Photos shown on the pre-auth sign-in page's scrolling gallery. Global (not\n// workspace-scoped) since the sign-in page has no workspace context yet.\n\nmodel LoginPhoto {\n  id          String   @id @default(cuid())\n  r2Key       String\n  contentType String?\n  column      String   @default(\"a\") // \"a\" (left, scrolls up) | \"b\" (right, scrolls down)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  @@index([column, order])\n}\n\n// ─── App Branding ───────────────────────────────────────────────────────────────\n// Uploaded logo/icon assets (favicon, PWA icons, web logo, OG image) managed in\n// Settings → App Logo. Global (not workspace-scoped): the favicon, manifest and\n// sign-in page all render before any workspace context exists. One row per\n// concrete served asset — Android slots store a row per size (192 + 512).\n\nmodel BrandingAsset {\n  id          String   @id @default(cuid())\n  slot        String   @unique // favicon | appleTouchIcon | androidAny192 | androidAny512 | androidMaskable192 | androidMaskable512 | webLogo | ogImage | androidMonochrome | iosSplash\n  r2Key       String\n  contentType String\n  fileName    String\n  width       Int      @default(0)\n  height      Int      @default(0)\n  size        Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ─── Publish Schedule ────────────────────────────────────────────────────────────\n\nmodel PublishItem {\n  id            String    @id @default(cuid())\n  workspaceId   String\n  projectId     String\n  taskId        String    @unique\n  scheduledDate DateTime\n  scheduledBy   String // WorkspaceMember ID\n  published     Boolean   @default(false)\n  publishedAt   DateTime?\n  notes         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  workspace Workspace       @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  project   Project         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  task      Task            @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  scheduler WorkspaceMember @relation(\"PublishScheduler\", fields: [scheduledBy], references: [id], onDelete: Cascade)\n\n  @@index([projectId, scheduledDate])\n  @@index([workspaceId, scheduledDate])\n}\n\nenum CustomFieldEntity {\n  COMPANY\n  CONTACT\n  DEAL\n}\n\nenum CustomFieldType {\n  TEXT\n  NUMBER\n  DATE\n  DROPDOWN\n  CHECKBOX\n  URL\n  PHONE\n}\n"
}

